import React, { useRef, useEffect, useState } from 'react';

function useVisible(threshold = 0.1) {
  const ref = useRef(null);
  const [vis, setVis] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if(e.isIntersecting) setVis(true); }, { threshold });
    if(ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, vis];
}

const devProjects = [
  {
    title: 'Campus Event App',
    desc: 'Aplikasi mobile untuk manajemen event kampus. Users bisa daftar, lihat jadwal, dan dapat notifikasi real-time.',
    tech: ['React Native', 'Firebase', 'Node.js'],
    color: 'var(--rose)',
    accent: 'var(--rose-deep)',
    emoji: '📱',
    tag: 'Mobile App',
  },
  {
    title: 'Student Portal Web',
    desc: 'Website portal mahasiswa dengan fitur absensi online, nilai akademik, dan pengumuman kampus yang terintegrasi.',
    tech: ['React JS', 'Express', 'MySQL'],
    color: 'var(--sky)',
    accent: '#4a90d9',
    emoji: '🌐',
    tag: 'Web App',
  },
  {
    title: 'Inventory Management System',
    desc: 'Sistem manajemen inventaris untuk koperasi kampus, lengkap dengan dashboard analytics dan laporan otomatis.',
    tech: ['Next.js', 'PostgreSQL', 'Chart.js'],
    color: 'var(--mint)',
    accent: 'var(--mint-deep)',
    emoji: '📊',
    tag: 'Web App',
  },
  {
    title: 'Study Group Finder',
    desc: 'Platform untuk menghubungkan mahasiswa yang ingin belajar bersama berdasarkan mata kuliah dan jadwal.',
    tech: ['Vue.js', 'Socket.io', 'MongoDB'],
    color: 'var(--butter)',
    accent: '#d4a017',
    emoji: '🤝',
    tag: 'Full Stack',
  },
];

const designProjects = [
  {
    title: 'Brand Identity — Startup Kampus',
    desc: 'Desain identitas visual lengkap untuk startup mahasiswa: logo, color palette, typography, dan brand guidelines.',
    tech: ['Illustrator', 'Photoshop', 'Figma'],
    color: 'var(--lavender)',
    accent: 'var(--lav-deep)',
    emoji: '🎨',
    tag: 'Branding',
  },
  {
    title: 'Poster Series — Dies Natalis',
    desc: 'Seri poster digital untuk acara Dies Natalis kampus. Menggabungkan elemen tradisional dengan estetika modern.',
    tech: ['Photoshop', 'Illustrator'],
    color: 'var(--peach)',
    accent: '#e07850',
    emoji: '🖼️',
    tag: 'Print Design',
  },
  {
    title: 'UI/UX Design — Food Delivery',
    desc: 'Desain antarmuka aplikasi food delivery untuk kantin kampus, fokus pada kemudahan penggunaan dan visual appealing.',
    tech: ['Figma', 'Principle', 'After Effects'],
    color: 'var(--rose)',
    accent: 'var(--rose-deep)',
    emoji: '🍱',
    tag: 'UI/UX',
  },
  {
    title: 'Social Media Kit — HIMA',
    desc: 'Template konten media sosial untuk Himpunan Mahasiswa — Instagram posts, stories, dan highlights covers.',
    tech: ['Canva Pro', 'Photoshop', 'Illustrator'],
    color: 'var(--mint)',
    accent: 'var(--mint-deep)',
    emoji: '📲',
    tag: 'Social Media',
  },
];

function ProjectCard({ project, index, vis }) {
  const [hovered, setHovered] = useState(false);

  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        background: hovered ? project.color : 'var(--card-bg)',
        border: `1.5px solid ${hovered ? project.color : 'rgba(0,0,0,0.06)'}`,
        borderRadius: 'var(--radius-lg)',
        padding: '2rem',
        cursor: 'pointer',
        transition: 'all 0.4s cubic-bezier(.4,0,.2,1)',
        transform: vis ? (hovered ? 'translateY(-8px) scale(1.02)' : 'translateY(0) scale(1)') : 'translateY(30px) scale(0.97)',
        opacity: vis ? 1 : 0,
        transitionDelay: `${index * 0.1}s`,
        boxShadow: hovered ? `0 20px 60px ${project.color}` : '0 4px 20px rgba(0,0,0,0.05)',
        backdropFilter: 'blur(10px)',
        display: 'flex', flexDirection: 'column', gap: '1rem',
      }}
    >
      {/* Top row */}
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
        <div style={{
          width: 56, height: 56, borderRadius: 'var(--radius-sm)',
          background: project.color, display:'flex', alignItems:'center', justifyContent:'center',
          fontSize: '1.8rem',
          border: `2px solid rgba(255,255,255,0.6)`,
        }}>{project.emoji}</div>
        <span style={{
          fontFamily: 'var(--font-mono)', fontSize: '0.7rem', letterSpacing:'0.08em',
          textTransform: 'uppercase', color: project.accent,
          background: `${project.color}`,
          padding: '0.3rem 0.8rem', borderRadius: '99px',
          border: `1px solid ${project.accent}40`,
        }}>{project.tag}</span>
      </div>

      {/* Title */}
      <h3 style={{
        fontFamily: 'var(--font-display)', fontWeight: 700,
        fontSize: '1.25rem', lineHeight: 1.25,
        color: 'var(--text)',
      }}>{project.title}</h3>

      {/* Desc */}
      <p style={{
        fontFamily: 'var(--font-body)', fontSize: '0.9rem',
        lineHeight: 1.65, color: 'var(--text-soft)', flex: 1,
      }}>{project.desc}</p>

      {/* Tech tags */}
      <div style={{ display:'flex', flexWrap:'wrap', gap:'0.5rem' }}>
        {project.tech.map(t => (
          <span key={t} style={{
            fontFamily: 'var(--font-mono)', fontSize: '0.72rem',
            color: 'var(--text-soft)', background: 'rgba(0,0,0,0.05)',
            padding: '0.25rem 0.7rem', borderRadius: '99px',
            border: '1px solid rgba(0,0,0,0.08)',
          }}>{t}</span>
        ))}
      </div>

      {/* Arrow */}
      <div style={{
        display:'flex', alignItems:'center', gap:'0.4rem',
        fontFamily: 'var(--font-body)', fontWeight: 500,
        fontSize: '0.85rem', color: project.accent,
        marginTop: '0.25rem',
        transform: hovered ? 'translateX(4px)' : 'none',
        transition: 'transform 0.3s ease',
      }}>
        Lihat Detail →
      </div>
    </div>
  );
}

export default function Projects() {
  const [ref, vis] = useVisible();
  const [tab, setTab] = useState('dev');

  const projects = tab === 'dev' ? devProjects : designProjects;

  return (
    <section id="projects" ref={ref} style={{
      padding: 'var(--section-pad)',
      background: 'linear-gradient(180deg, var(--white) 0%, var(--peach) 100%)',
      position: 'relative', overflow: 'hidden',
    }}>
      <div style={{
        position: 'absolute', bottom:'-15%', left:'-8%',
        width:400, height:400,
        background:'var(--rose)', borderRadius:'50%',
        opacity:0.25, filter:'blur(80px)',
      }} />

      <div style={{ maxWidth: 1100, margin: '0 auto', position: 'relative' }}>
        {/* Header */}
        <div style={{ marginBottom: '3rem' }}>
          <p style={{
            fontFamily: 'var(--font-mono)', fontSize: '0.78rem',
            letterSpacing: '0.15em', color: 'var(--rose-deep)',
            textTransform: 'uppercase', marginBottom: '0.75rem',
            opacity: vis ? 1 : 0, transition: 'opacity 0.6s ease',
          }}>✦ My Work</p>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-end', flexWrap:'wrap', gap:'1.5rem' }}>
            <h2 style={{
              fontFamily: 'var(--font-display)', fontWeight: 900,
              fontSize: 'clamp(2rem, 5vw, 3.5rem)', lineHeight: 1.1,
              letterSpacing: '-0.02em',
              opacity: vis ? 1 : 0, transform: vis ? 'none' : 'translateY(20px)',
              transition: 'all 0.7s 0.1s ease',
            }}>
              Project <em style={{color:'var(--rose-deep)'}}>Kampus</em>
            </h2>

            {/* Tabs */}
            <div style={{
              display:'flex', gap:'0.4rem',
              background: 'rgba(255,255,255,0.8)', backdropFilter:'blur(10px)',
              borderRadius:'99px', padding:'0.35rem',
              border:'1px solid rgba(0,0,0,0.08)',
              opacity: vis ? 1 : 0, transition: 'opacity 0.7s 0.2s ease',
            }}>
              {[
                { id:'dev',    label:'💻 App & Web' },
                { id:'design', label:'🎨 Graphic Design' },
              ].map(t => (
                <button key={t.id} onClick={() => setTab(t.id)} style={{
                  padding: '0.6rem 1.4rem', borderRadius:'99px',
                  border:'none', cursor:'pointer',
                  fontFamily:'var(--font-body)', fontWeight:500, fontSize:'0.88rem',
                  background: tab===t.id ? (t.id==='dev' ? 'var(--rose-deep)' : 'var(--lav-deep)') : 'transparent',
                  color: tab===t.id ? '#fff' : 'var(--text-soft)',
                  transition:'all 0.3s ease',
                }}>{t.label}</button>
              ))}
            </div>
          </div>
        </div>

        {/* Grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
          gap: '1.5rem',
        }}>
          {projects.map((p, i) => (
            <ProjectCard key={`${tab}-${i}`} project={p} index={i} vis={vis} />
          ))}
        </div>
      </div>
    </section>
  );
}
